:host {
    display: block;
    width: 100%;
    height: 100vh;
    overflow: hidden;

    --_sidebar-width: var(--workspace-shell-sidebar-width, 224px);
    --_sidebar-collapsed-width: 0px;
    --_secondary-sidebar-width: var(--workspace-shell-secondary-width, 248px);
    --_sidebar-bg: var(--bg-sidebar, var(--bg-surface));
    --_sidebar-border: var(--border-default);
    --_content-bg: var(--bg-base);
    --_content-padding: var(--workspace-shell-content-padding, 30px);
    --_focus-ring: var(--primary-base, #2563eb);
    --_mobile-toolbar-height: 52px;

    --ctx-bg: var(--_content-bg);
    --ctx-fg: var(--text-main);
    --ctx-fg-muted: var(--text-muted);
    --ctx-border: var(--border-default);
}

.app-container {
    display: flex;
    width: 100%;
    height: 100%;
    min-width: 0;
}

.mobile-toolbar,
.mobile-backdrop {
    display: none;
}

.skip-link {
    position: absolute;
    z-index: 1000;
    top: 0;
    left: 0;
    padding: 0.5rem 1rem;
    transform: translateY(-150%);
    border: 2px solid var(--_focus-ring);
    border-radius: 4px;
    background: var(--_content-bg);
    color: var(--_focus-ring);
    text-decoration: none;
}

.skip-link:focus-visible {
    transform: translateY(0);
    outline: 2px solid var(--_focus-ring);
    outline-offset: 2px;
}

.app-sidebar,
.secondary-sidebar {
    flex-shrink: 0;
    height: 100%;
    overflow: hidden;
    border-right: 1px solid var(--_sidebar-border);
    background-color: var(--_sidebar-bg);
}

.app-sidebar {
    width: var(--_sidebar-width);
}

.secondary-sidebar {
    width: var(--_secondary-sidebar-width);
}

.secondary-sidebar[hidden] {
    display: none;
}

.app-nav,
.secondary-nav {
    height: 100%;
    overflow-y: auto;
}

::slotted([slot="sidebar"]),
::slotted([slot="secondary-sidebar"]) {
    width: 100%;
    --ctx-bg: var(--_sidebar-bg);
    --ctx-fg: var(--text-main);
    --ctx-fg-muted: var(--text-muted);
    --ctx-border: var(--_sidebar-border);
    --menu-border-width: 0;
}

::slotted(:not([slot])) {
    --ctx-bg: var(--_content-bg);
    --ctx-fg: var(--text-main);
    --ctx-fg-muted: var(--text-muted);
    --ctx-border: var(--border-default);
}

:host([collapsed]) .app-sidebar {
    width: var(--_sidebar-collapsed-width);
    border-right-width: 0;
}

.app-content {
    box-sizing: border-box;
    flex-grow: 1;
    height: 100%;
    min-width: 0;
    overflow-y: auto;
    padding: var(--_content-padding);
    background-color: var(--_content-bg);
}

.app-content:focus-visible {
    outline: 2px solid var(--_focus-ring);
    outline-offset: -4px;
}

@media (prefers-reduced-motion: no-preference) {
    .app-sidebar {
        transition:
            width 0.25s cubic-bezier(0.4, 0, 0.2, 1),
            border-right-width 0.25s cubic-bezier(0.4, 0, 0.2, 1);
    }

    .skip-link {
        transition: transform 0.2s ease-out;
    }
}

@media (max-width: 720px) {
    :host {
        width: 100%;
        max-width: 100vw;
        --_content-padding: var(--workspace-shell-mobile-padding, 16px);
    }

    .app-container {
