export function upgradeProperty(element: HTMLElement, property: string): void {
    if (!Object.hasOwn(element, property)) {
        return;
    }
    const value = (element as unknown as Record<string, unknown>)[property];
    delete (element as unknown as Record<string, unknown>)[property];
    (element as unknown as Record<string, unknown>)[property] = value;
}

export function getMenuItems(slot: HTMLSlotElement | null): HTMLElement[] {
    if (!slot) {
        return [];
    }
    return slot
        .assignedElements({ flatten: true })
        .filter(
            (element): element is HTMLElement =>
                element instanceof HTMLElement &&
                element.tagName.toLowerCase() === "workspace-lateral-menu-item" &&
                !element.hasAttribute("disabled"),
        );
}

import { getMenuItems } from "./compute";

export function handleKeydown(host: HTMLElement, event: KeyboardEvent): void {
    const slot = host.shadowRoot?.querySelector("slot:not([name])") as HTMLSlotElement | null;
    const items = getMenuItems(slot);
    if (items.length === 0) {
        return;
    }

    const active = document.activeElement;
    const currentIndex = items.findIndex((item) => item === active || item.contains(active));
    let nextIndex = -1;
    switch (event.key) {
        case "ArrowDown":
            nextIndex = currentIndex < 0 ? 0 : (currentIndex + 1) % items.length;
            break;
        case "ArrowUp":
            nextIndex = currentIndex < 0 ? items.length - 1 : (currentIndex - 1 + items.length) % items.length;
            break;
        case "Home":
            nextIndex = 0;
            break;
        case "End":
            nextIndex = items.length - 1;
            break;
        default:
            return;
    }

    event.preventDefault();
    items[nextIndex]?.focus();
}

